 "required": ["query", "limit"],
 },
)

ADD_BOOK = Tool(
 name="add_book",
 description="Add a book to the catalog.",
 input_schema={
 "type": "object",
 "properties": {"title": {"type": "string"}, "author": {"type": "string"}, "year": {"type": "integer"}},
 "required": ["title", "author", "year"],
 },
)

